   153	\begin{lemma}[Product form and Pauli relations of the pulled-apart observables]\label{lem:tildew-product-form}
   154		\lean{MIPStarRE.QPBT.tildeObs_eq_heteroKron}
   155		\lean{MIPStarRE.QPBT.tildeObs_isHermitian}
   156		\lean{MIPStarRE.QPBT.tildeObs_mul_self}
